#![allow(dead_code,unused_imports)]
pub use quantum_ecc::circuit;
include!("prefix.rs");
mod observed_sim;
use std::{fs,path::Path,io::BufWriter};
const DEFAULT_ZSTD_LEVEL:i32=3;
#[derive(Clone)]struct Row{site:usize,finalsite:usize,op:Op,rep:Option<Op>,action:String}
fn rawhash(ops:&[Op])->String{let mut h=sha3::Sha3_256::default();for o in ops{sha3::Digest::update(&mut h,(o.kind as u32).to_le_bytes());sha3::Digest::update(&mut h,[0u8;4]);for v in[o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]{sha3::Digest::update(&mut h,v.to_le_bytes());}}format!("{:x}",sha3::Digest::finalize(h))}
fn main(){if std::env::args().nth(1).as_deref()==Some("@t0"){t0_witness();return;}if std::env::args().nth(1).as_deref()==Some("@t0table"){t0_table(&std::env::args().nth(2).unwrap());return;}let root="/home/hclau/ecdsa_research/payload-model-20261016";let src="/home/hclau/ecdsa_research/product-exact-20261015/tip";let finalops=load_ops(&format!("{src}/ops.bin")).unwrap();let text=fs::read_to_string(format!("{src}/src/point_add/census_cut_data.txt")).unwrap();let mut rows=Vec::new();let mut deleted=0;for l in text.lines().filter(|l|!l.trim().is_empty()&&!l.starts_with('#')){let f:Vec<&str>=l.split_whitespace().collect();assert_eq!(f.len(),7);let site:usize=f[0].parse().unwrap();let mut o=Op::empty();o.kind=match f[1]{"ccx"=>OperationType::CCX,"ccz"=>OperationType::CCZ,_=>panic!()};o.q_control2=QubitId(f[2].parse().unwrap());o.q_control1=QubitId(f[3].parse().unwrap());o.q_target=QubitId(f[4].parse().unwrap());if f[5]!="-"{o.c_condition=BitId(f[5].parse().unwrap());}o.validate();let mut rep=o;rep.q_control2=QubitId(u64::MAX);let rep=if f[6]=="del"{None}else if let Some(a)=f[6].strip_prefix("cx:"){rep.kind=OperationType::CX;rep.q_control1=QubitId(a.parse().unwrap());Some(rep)}else if let Some(ab)=f[6].strip_prefix("cz:"){let(a,b)=ab.split_once(',').unwrap();rep.kind=OperationType::CZ;rep.q_control1=QubitId(a.parse().unwrap());rep.q_target=QubitId(b.parse().unwrap());Some(rep)}else{panic!()};rows.push(Row{site,finalsite:site-deleted,op:o,rep,action:f[6].to_string()});deleted+=usize::from(rep.is_none());}
 let mut pre=Vec::with_capacity(finalops.len()+deleted);let mut cursor=0;for row in &rows{assert_eq!(pre.len()+row.finalsite-cursor,row.site);pre.extend_from_slice(&finalops[cursor..row.finalsite]);pre.push(row.op);cursor=row.finalsite;if let Some(rep)=row.rep{assert_eq!(finalops[cursor],rep);cursor+=1;}}pre.extend_from_slice(&finalops[cursor..]);
 let anchors=fs::read_to_string(format!("{src}/src/point_add/census_anchors.txt")).unwrap();for (l,row)in anchors.lines().zip(&rows){let f:Vec<&str>=l.split_whitespace().collect();assert_eq!(f[0].parse::<usize>().unwrap(),row.site);let k:usize=f[1].parse().unwrap();assert_eq!(rawhash(&pre[row.site-k..row.site+k+1]),f[2],"anchor {}",row.site);}println!("RECONSTRUCTED_PRE_CENSUS rows={} inserted={deleted} original_ops={} final_ops={} all_144_source_anchors_exact=true",rows.len(),pre.len(),finalops.len());write_ops(&pre,&Path::new(root).join("before-census.bin")).unwrap();
 let(nq,nb,_,regs)=analyze_ops(finalops.iter());let points:Vec<[U256;6]>=fs::read_to_string(format!("{root}/packets/audit.tsv")).unwrap().lines().map(|l|l.split_whitespace().skip(1).map(|s|U256::from_str_radix(s.trim_start_matches("0x"),16).unwrap()).collect::<Vec<_>>().try_into().unwrap()).collect();assert!(points.len()<=64);
 for mode in 0..2{let ops=if mode==0{&pre}else{&finalops};let mut h=Shake256::default();h.update(b"payload-model-cut-proof-20261016");let mut rng=h.finalize_xof();let mut rr=rng.clone();let mut s=observed_sim::Simulator::new(nq as usize,nb as usize,&mut rng);let mut r=Simulator::new(nq as usize,nb as usize,&mut rr);for(lane,v)in points.iter().enumerate(){for k in 0..4{s.set_register(&regs[k],v[k],lane);r.set_register(&regs[k],v[k],lane);}}let mut cursor=0;let mut base=u64::MAX;let mut stack=Vec::new();s.apply_observed(ops.iter(),|idx,s,o,_cond|{
 while cursor<rows.len()&&idx==if mode==0{rows[cursor].site}else{rows[cursor].finalsite}{let row=&rows[cursor];let mut cond=base;if row.op.c_condition.0!=u64::MAX{cond&=s.bits[row.op.c_condition.0 as usize];}let mut original=s.qubits[row.op.q_control1.0 as usize]&s.qubits[row.op.q_control2.0 as usize];if row.op.kind==OperationType::CCZ{original&=s.qubits[row.op.q_target.0 as usize];}let replacement=match row.rep{None=>0,Some(rep)if rep.kind==OperationType::CX=>s.qubits[rep.q_control1.0 as usize],Some(rep)=>s.qubits[rep.q_control1.0 as usize]&s.qubits[rep.q_target.0 as usize]};let diff=cond&(original^replacement);if diff!=0{for lane in 0..points.len(){if diff>>lane&1!=0{println!("CUT_ACTIVE mode={mode} shot={lane} row={cursor} site={} finalsite={} kind={:?} a={} b={} t={} action={}",row.site,row.finalsite,row.op.kind,row.op.q_control1.0,row.op.q_control2.0,row.op.q_target.0,row.action);}}}cursor+=1;}
 if o.kind==OperationType::PushCondition{stack.push(base);base&=s.bits[o.c_condition.0 as usize];}else if o.kind==OperationType::PopCondition{base=stack.pop().unwrap();}
 });assert_eq!(cursor,rows.len());r.apply_iter(ops.iter());assert_eq!(s.qubits,r.qubits);assert_eq!(s.bits,r.bits);assert_eq!(s.phase,r.phase);assert_eq!(s.stats.toffoli_gates,r.stats.toffoli_gates);for(lane,v)in points.iter().enumerate(){let x=s.get_register(&regs[0],lane);let y=s.get_register(&regs[1],lane);println!("CUT_FINAL mode={mode} shot={lane} correct={} x={x:#x} y={y:#x} expected_x={:#x} expected_y={:#x} all_state_equal=true",x==v[4]&&y==v[5],v[4],v[5]);}println!("CUT_PROTECTED_FULL_EQUAL mode={mode} shots={} qubits={nq} bits={nb} phase=true toffoli=true",points.len());}
}
fn t0_witness(){let ops=load_ops("/home/hclau/ecdsa_research/payload-model-20261016/t0-probe-ops.bin").unwrap();let(nq,nb,_,_)=analyze_ops(ops.iter());let reg=|start:u64,n:u64|(start..start+n).map(|i|QubitOrBit::Qubit(QubitId(i))).collect::<Vec<_>>();let(r0,r1,letter)=(reg(0,256),reg(256,256),reg(512,5));let p=secp256k1().modulus;let half=|v:U256|if v.bit(0){(v>>1)+(p>>1)+U256::from(1)}else{v>>1};
 for seed in 0..8u64{let mut h=Shake256::default();h.update(b"source-component-one-sided-counterexample");h.update(&seed.to_le_bytes());let mut rng=h.finalize_xof();let mut s=Simulator::new(nq as usize,nb as usize,&mut rng);let input=U256::from(0x1000003d1u64);s.set_register(&r0,input,0);s.set_register(&letter,U256::from(5),0);s.apply_iter(ops.iter());let source=s.get_register(&r0,0);let ideal=half(half(half(p-(U256::from(1)<<255))));let generic=ideal+U256::from(1u64<<54);assert_eq!(s.get_register(&r1,0),U256::from(1)<<255);assert_eq!(source,ideal);assert_ne!(source,generic);println!("T0_ONE_SIDED_PROTECTED_WITNESS seed={seed} T={input:#x} signs=1,0,1 extra=0 source={source:#x} ideal={ideal:#x} generic_model={generic:#x} source_correct=true generic_model_wrong=true component_only=true");}
 println!("T0_ONE_SIDED_PASS seeds=8 exact_source_component=true full_point_witness=false score=NONE");}
fn t0_table(path:&str){let ops=load_ops("/home/hclau/ecdsa_research/payload-model-20261016/t0-probe-ops.bin").unwrap();let(nq,nb,_,_)=analyze_ops(ops.iter());let reg=|start:u64,n:u64|(start..start+n).map(|i|QubitOrBit::Qubit(QubitId(i))).collect::<Vec<_>>();let(r0,r1,letter)=(reg(0,256),reg(256,256),reg(512,5));let rows:Vec<[U256;4]>=fs::read_to_string(path).unwrap().lines().map(|l|l.split_whitespace().skip(1).map(|v|U256::from_str_radix(v.trim_start_matches("0x"),16).unwrap()).collect::<Vec<_>>().try_into().unwrap()).collect();assert_eq!(rows.len(),928);
 for seed in 0..8u64{for(batch,rows)in rows.chunks(64).enumerate(){let mut h=Shake256::default();h.update(b"source-t0-model-table-differential");h.update(&seed.to_le_bytes());h.update(&(batch as u64).to_le_bytes());let mut rng=h.finalize_xof();let mut rr=rng.clone();let mut s=observed_sim::Simulator::new(nq as usize,nb as usize,&mut rng);let mut r=Simulator::new(nq as usize,nb as usize,&mut rr);for(lane,row)in rows.iter().enumerate(){s.set_register(&r0,row[0],lane);s.set_register(&letter,row[1],lane);r.set_register(&r0,row[0],lane);r.set_register(&letter,row[1],lane);}s.apply_iter(ops.iter());r.apply_iter(ops.iter());assert_eq!(s.qubits,r.qubits);assert_eq!(s.bits,r.bits);assert_eq!(s.phase,r.phase);assert_eq!(s.stats.toffoli_gates,r.stats.toffoli_gates);for(lane,row)in rows.iter().enumerate(){assert_eq!(r.get_register(&r0,lane),row[3],"Python model output seed{seed} batch{batch} lane{lane}");assert_eq!(r.get_register(&r1,lane),row[2],"Python model source seed{seed} batch{batch} lane{lane}");}}
 println!("SOURCE_T0_MODEL_BOUNDARY_PASS seed={seed} cases=928 all_qubits=true all_bits=true phase=true toffolis=true unsigned_model_outputs=true");}println!("SOURCE_T0_MODEL_BOUNDARIES_COMPLETE cases=928 seeds=8 total_shots=7424 exact_source_component=true score=NONE");}
